class ExpressionEvaluator:
    def __init__(self, expression):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def parse_number(self):
        number = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number += self.current_char
            self.advance()
        return float(number)

    def parse_expression(self):
        self.skip_whitespace()
        result = self.parse_term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            term = self.parse_term()
            if op == '+':
                result += term
            elif op == '-':
                result -= term
        return result

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            factor = self.parse_factor()
            if op == '*':
                result *= factor
            elif op == '/':
                result /= factor
        return result

    def parse_factor(self):
        self.skip_whitespace()
        if self.current_char == '(':
            self.advance()
            result = self.parse_expression()
            self.skip_whitespace()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()
        elif self.current_char.isdigit() or (self.current_char == '.' or (self.current_char == '-' and self.peek().isdigit())):
            return self.parse_number()
        else:
            self.error()

    def peek(self):
        peek_pos = self.position + 1
        if peek_pos < len(self.expression):
            return self.expression[peek_pos]
        return None

