def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the shunting-yard algorithm.
    Supports +, -, *, /, parentheses, and floating-point numbers.
    """
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def parse_expression(expression):
        operators = []
        values = []
        i = 0
        num = ''
        while i < len(expression):
            char = expression[i]

            if char.isspace():
                i += 1
                continue

            if char.isdigit() or char == '.':
                num += char

            elif char in ('+', '-', '*', '/'):
                if num:
                    values.append(float(num))
                    num = ''
                while (operators and precedence(operators[-1]) >= precedence(char)):
                    apply_operator(operators, values)
                operators.append(char)

            elif char == '(':
                operators.append(char)

            elif char == ')':
                if num:
                    values.append(float(num))
                    num = ''
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove the '(' from stack

            i += 1

        if num:
            values.append(float(num))

        while operators:
            apply_operator(operators, values)

        return values[0]

    return parse_expression(expr)

