    """
    Evaluates an arithmetic expression using a recursive descent parsing approach.
    Supports +, -, *, /, parentheses, and floating-point numbers.
    """

    def parse_expression(index):
        value = parse_term(index)
        while index[0] < len(expr):
            if expr[index[0]] in '+-':
                op = expr[index[0]]
                index[0] += 1  # Move past operator
                value = apply_operator(value, op, parse_term(index))
            else:
                break
        return value

    def parse_term(index):
        value = parse_factor(index)
        while index[0] < len(expr):
            if expr[index[0]] in '*/':
                op = expr[index[0]]
                index[0] += 1  # Move past operator
                value = apply_operator(value, op, parse_factor(index))
            else:
                break
        return value

    def parse_factor(index):
        if expr[index[0]] == '(':
            index[0] += 1  # Skip the '('
            value = parse_expression(index)
            index[0] += 1  # Skip the ')'
            return value
        else:
            num_str = ''
            while (index[0] < len(expr) and (expr[index[0]].isdigit() or expr[index[0]] == '.')):
                num_str += expr[index[0]]
                index[0] += 1
            return float(num_str)

    def apply_operator(left, op, right):
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        if op == '*':
            return left * right
        if op == '/':
            return left / right

    # Start parsing from the first character
    return parse_expression([0])

