    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm 
    to convert the infix expression to postfix notation, which is then 
    evaluated. Supports +, -, *, /, parentheses, and floating-point numbers.
    """

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def to_postfix(expression):
        output = []
        stack = []
        number = ''

        for char in expression:
            if char.isdigit() or char == '.':
                number += char
            else:
                if number:
                    output.append(float(number))
                    number = ''
                if char in "+-*/":
                    while (stack and precedence(stack[-1]) >= precedence(char)):
                        output.append(stack.pop())
                    stack.append(char)
                elif char == '(':
                    stack.append(char)
                elif char == ')':
                    while stack and stack[-1] != '(':
                        output.append(stack.pop())
                    stack.pop()  # Remove the '(' from the stack

        if number:
            output.append(float(number))

        while stack:
            output.append(stack.pop())

        return output

    def evaluate_postfix(postfix):
        stack = []

        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                right = stack.pop()
                left = stack.pop()
                if token == '+':
                    stack.append(left + right)
                elif token == '-':
                    stack.append(left - right)
                elif token == '*':
                    stack.append(left * right)
                elif token == '/':
                    stack.append(left / right)

        return stack[0]

    postfix_expr = to_postfix(expr)
    return evaluate_postfix(postfix_expr)

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a recursive descent parser technique. 
    This method directly processes the expression according to the grammar of 
    arithmetic operations, handling operator precedence and parentheses.
    """

    class Parser:
        def __init__(self, expression):
            self.tokens = self.tokenize(expression)
            self.pos = 0

        def tokenize(self, expr):
            tokens = []
            number = ''
            for char in expr:
                if char.isdigit() or char == '.':
                    number += char
                else:
                    if number:
                        tokens.append(float(number))
                        number = ''
                    if char in "+-*/()":
                        tokens.append(char)
            if number:
                tokens.append(float(number))
            return tokens

        def parse_expression(self):
            value = self.parse_term()
            while self.pos < len(self.tokens) and self.tokens[self.pos] in ('+', '-'):
                op = self.tokens[self.pos]
                self.pos += 1
                value = self.apply_operator(value, self.parse_term(), op)
            return value

        def parse_term(self):
            value = self.parse_factor()
            while self.pos < len(self.tokens) and self.tokens[self.pos] in ('*', '/'):
                op = self.tokens[self.pos]
                self.pos += 1
                value = self.apply_operator(value, self.parse_factor(), op)
            return value

        def parse_factor(self):
            if self.pos < len(self.tokens):
                token = self.tokens[self.pos]
                if isinstance(token, float):
                    self.pos += 1
                    return token
                elif token == '(':
                    self.pos += 1
                    value = self.parse_expression()
                    self.pos += 1  # skip ')'
                    return value
                elif token == '-':
                    self.pos += 1
                    return -self.parse_factor()
                elif token == '+':
                    self.pos += 1
                    return self.parse_factor()
            raise ValueError("Unexpected token")

        def apply_operator(self, left, right, op):
            if op == '+':
                return left + right
            elif op == '-':
                return left - right
            elif op == '*':
                return left * right
            elif op == '/':
                return left / right
            raise ValueError("Invalid operator")

    parser = Parser(expr.replace(" ", ""))
    return parser.parse_expression()
